// swap.mjs — the name-swap control (arm D): every surface of the six referents replaced, consistently, by invented names; the case forms of an
// invented name are generated by the SAME declension table (UniMorph, janus priors/declension-rus.json) that folded the originals, in the way
// khora native/adapters/text/folded-card.js generates them (an observed oblique token reaches a base token by a rule `from -> to`; the invented
// oblique is the invented base with `to` replaced by `from`). Pure; no model; no network.
import { foldRu, escapeRe } from "./lib.mjs";

const cap = (w, like) => (like && like[0] === like[0].toUpperCase() && like[0] !== like[0].toLowerCase() ? w[0].toUpperCase() + w.slice(1) : w);
const WORD = /[\p{L}]+(?:-[\p{L}]+)*/gu;

/**
 * pairsFor({ decl, prior, observed }) -> { pairs: Map(observed token -> invented token), unmapped: [...] }
 *   decl     { <base token as written>: <invented base token> }
 *   observed the capitalised tokens of the six beings' surfaces, as written
 */
export function pairsFor({ decl, prior, observed }) {
  const keys = Object.keys(decl), pairs = new Map(), unmapped = [];
  for (const tok of observed) {
    let hit = null;
    for (const k of keys) if (foldRu(k) === foldRu(tok)) { hit = [decl[k], null]; break; }
    if (!hit) {
      outer: for (const rule of prior.rules) {
        if (!tok.toLowerCase().endsWith(rule.from)) continue;
        const stem = tok.toLowerCase().slice(0, tok.length - rule.from.length);
        for (const k of keys) if (foldRu(stem + rule.to) === foldRu(k)) { hit = [decl[k], rule]; break outer; }
      }
    }
    if (!hit) { unmapped.push(tok); continue; }
    const [invented, rule] = hit;
    if (!rule) pairs.set(tok, cap(invented, tok));
    else if (invented.toLowerCase().endsWith(rule.to)) pairs.set(tok, cap(invented.slice(0, invented.length - rule.to.length) + rule.from, tok));
    else { pairs.set(tok, cap(invented, tok)); unmapped.push(`${tok} (the invented name does not end as the rule needs)`); }
  }
  return { pairs, unmapped };
}

/** the inverse (invented token -> original token); throws if two originals share one invented token. */
export function inverse(pairs) {
  const inv = new Map();
  for (const [o, n] of pairs) { if (inv.has(n) && inv.get(n) !== o) throw new Error(`the swap is not injective: ${n} <- ${inv.get(n)}, ${o}`); inv.set(n, o); }
  return inv;
}

const wordRe = (w) => new RegExp(`(?<![\\p{L}\\p{N}])${escapeRe(w)}(?![\\p{L}\\p{N}])`, "gu");

/**
 * applySwap(text, { pairs, phrases, shared }): first each whole surface (a phrase of one or more tokens) of the six beings, longest first, with its
 * tokens mapped; then each remaining single token that is not SHARED with the name of another being (a token like «Анна» also names «Анна Михайловна»
 * and is replaced only inside the six beings' own surfaces).
 */
export function applySwap(text, { pairs, phrases, shared }) {
  let out = text;
  const mapPhrase = (ph) => ph.replace(WORD, (t) => pairs.get(t) ?? t);
  const phs = [...new Set(phrases)].filter((p) => mapPhrase(p) !== p).sort((a, b) => b.length - a.length || (a < b ? -1 : 1));
  // phrases first, through placeholders so that a later pass cannot touch what was just written
  const hold = new Map();
  phs.forEach((p, i) => { const key = `\u0001${i}\u0002`; hold.set(key, mapPhrase(p)); out = out.replace(wordRe(p), key); });
  const toks = [...pairs.keys()].filter((t) => !shared.has(t)).sort((a, b) => b.length - a.length || (a < b ? -1 : 1));
  for (const t of toks) out = out.replace(wordRe(t), pairs.get(t));
  for (const [key, v] of hold) out = out.split(key).join(v);
  return out;
}

/** words of the text that begin with the stem of an original token (the leak check: a form the fold did not list). */
export function leaks(text, originals, { minStem = 4, cut = 2 } = {}) {
  const stems = [...new Set(originals.map((t) => foldRu(t)).map((t) => t.slice(0, Math.max(minStem, t.length - cut))))];
  const found = new Map();
  for (const m of text.matchAll(WORD)) {
    const w = foldRu(m[0]);
    for (const s of stems) if (w.startsWith(s)) { found.set(m[0], (found.get(m[0]) ?? 0) + 1); break; }
  }
  return [...found].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
}
